def _top_net_margin(ranked: Sequence[_RankedState]) -> float:
        if len(ranked) < 2:
            return 0.0
        top = ranked[0].score.net_rubric_bits
        for item in ranked[1:]:
            if not math.isclose(
                item.score.net_rubric_bits,
                top,
                rel_tol=1e-12,
                abs_tol=1e-12,
            ):
                return top - item.score.net_rubric_bits
        return 0.0
